import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  AccessibilityInfo,
  PanResponder,
  View,
  type AccessibilityActionEvent,
  type ViewStyle,
} from "react-native";
import {
  Canvas,
  ImageShader,
  RoundedRect,
  Shader,
  type SkImage,
} from "@shopify/react-native-skia";
import {
  cancelAnimation,
  runOnJS,
  useAnimatedReaction,
  useDerivedValue,
  useSharedValue,
  withSpring,
  type SharedValue,
} from "react-native-reanimated";
import { transitionEffect } from "./transitionShaders";
import {
  clamp,
  dragScroll,
  effectForTransition,
  rubber,
  scrub,
  snapTarget,
  springConfig,
  type TransitionEffect,
} from "./transitionMath";

export type GLTransitionPagerProps = {
  /** Prepared page textures, one per page. Draw each at least 2x the page size for crisp shader work. */
  pages: SkImage[];
  /** Accessibility name per page ("Dune", "Harbor"). Falls back to "Page N". */
  labels?: string[];
  /** Viewport size in layout points; pages fill it edge to edge. */
  width: number;
  height: number;
  /** Page corner radius, default 18. */
  radius?: number;
  /** Force one effect for every hop instead of cycling all four. */
  effect?: TransitionEffect;
  index: number;
  onIndexChange: (index: number) => void;
  /** Fires when a new page settles: wire expo-haptics here (the core has no haptics dependency). */
  onFeedback?: (event: "snap") => void;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  label?: string;
  style?: ViewStyle;
};

export function GLTransitionPager({
  pages,
  labels,
  width,
  height,
  radius = 18,
  effect,
  index,
  onIndexChange,
  onFeedback,
  slowMotion = false,
  reducedMotion,
  label = "Image pager",
  style,
}: GLTransitionPagerProps) {
  const count = pages.length;
  const last = Math.max(0, count - 1);
  const scroll = useSharedValue(clamp(index, 0, last));
  // Travel direction for directional effects: 1 moving forward, -1 back.
  const dir = useSharedValue(1);
  // Where the last touch began, in page units (0..1); the ripple grows from there.
  const touch = useSharedValue<[number, number]>([0.5, 0.5]);
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = !!reducedMotion || systemReduce;
  const mounted = useRef(true);
  const dragging = useRef(false);
  const settling = useRef(false);
  const destination = useRef(clamp(index, 0, last));
  const settledIndex = useRef(clamp(index, 0, last));
  const revision = useRef(0);
  const start = useRef(0);
  const latest = useRef({ slowMotion, reduce, onIndexChange, onFeedback, last });
  latest.current = { slowMotion, reduce, onIndexChange, onFeedback, last };

  useEffect(() => {
    mounted.current = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => mounted.current && setSystemReduce(v))
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      mounted.current = false;
      revision.current++;
      sub.remove();
      cancelAnimation(scroll);
    };
  }, [scroll]);

  const finish = (target: number, generation: number) => {
    if (!mounted.current || generation !== revision.current) return;
    settling.current = false;
    if (target !== settledIndex.current) {
      settledIndex.current = target;
      latest.current.onFeedback?.("snap");
    }
  };
  const settle = (target: number, velocityPages = 0) => {
    const generation = ++revision.current;
    destination.current = target;
    if (velocityPages !== 0) dir.value = velocityPages > 0 ? 1 : -1;
    cancelAnimation(scroll);
    if (latest.current.reduce) {
      scroll.value = target;
      settling.current = false;
      finish(target, generation);
      return;
    }
    settling.current = true;
    scroll.value = withSpring(
      target,
      {
        ...springConfig(latest.current.slowMotion),
        velocity: velocityPages / (latest.current.slowMotion ? 4 : 1),
        overshootClamping: false,
        energyThreshold: 1e-4,
      },
      (done) => {
        if (done) runOnJS(finish)(target, generation);
      },
    );
  };
  const go = (target: number) => {
    const next = clamp(Math.round(target), 0, latest.current.last);
    if (next === destination.current && !settling.current) return;
    dir.value = next > scroll.value ? 1 : -1;
    settle(next);
    latest.current.onIndexChange(next);
  };
  // Controlled prop: reverse from wherever the pager is.
  useEffect(() => {
    const clamped = clamp(index, 0, latest.current.last);
    if (destination.current !== clamped) {
      dir.value = clamped > scroll.value ? 1 : -1;
      settle(clamped);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [index]);
  // Changing speed or Reduce Motion mid-flight restarts the spring toward the same page.
  useEffect(() => {
    if (settling.current && !dragging.current) settle(destination.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slowMotion, reduce]);

  const responder = useMemo(
    () =>
      PanResponder.create({
        // At rest, horizontal drags take over. Mid-flight, any touch grabs the moving pages.
        onStartShouldSetPanResponder: () => settling.current,
        onMoveShouldSetPanResponderCapture: (_, g) =>
          Math.abs(g.dx) > 8 && Math.abs(g.dx) > Math.abs(g.dy) * 1.2,
        onPanResponderGrant: (evt) => {
          revision.current++;
          cancelAnimation(scroll);
          dragging.current = true;
          settling.current = false;
          start.current = scroll.value;
          touch.value = [
            clamp(evt.nativeEvent.locationX / Math.max(1, width)),
            clamp(evt.nativeEvent.locationY / Math.max(1, height)),
          ];
        },
        onPanResponderMove: (_, g) => {
          if (!dragging.current) return;
          const next = dragScroll(start.current, g.dx, width, latest.current.last);
          dir.value = next > scroll.value ? 1 : next < scroll.value ? -1 : dir.value;
          scroll.value = next;
        },
        onPanResponderRelease: (evt, g) => {
          if (!dragging.current) return;
          dragging.current = false;
          const velocityPages = (-g.vx * 1000) / Math.max(1, width);
          const tap = Math.abs(g.dx) < 6 && Math.abs(g.vx) < 0.15;
          if (tap) {
            // A tap on the left or right third walks one page that way; the middle stays.
            const x = evt.nativeEvent.locationX;
            const third = width / 3;
            const target =
              x < third ? destination.current - 1 : x > third * 2 ? destination.current + 1 : destination.current;
            go(target);
            return;
          }
          const target = snapTarget(scroll.value, velocityPages, latest.current.last);
          settle(target, velocityPages);
          latest.current.onIndexChange(target);
        },
        onPanResponderTerminate: () => {
          if (!dragging.current) return;
          dragging.current = false;
          settle(destination.current);
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [scroll, width, height],
  );

  const onAccessibility = (event: AccessibilityActionEvent) => {
    if (event.nativeEvent.actionName === "increment") go(destination.current + 1);
    if (event.nativeEvent.actionName === "decrement") go(destination.current - 1);
  };

  // The active hop: which two pages, how far, and which effect carries it. The texture pair lives
  // in React state (SkImage props are not shared-value reactive); it changes only when the scroll
  // crosses a page boundary, so the reaction fires at most once per boundary.
  const [hop, setHop] = useState(() => scrub(clamp(index, 0, last), last).from);
  useAnimatedReaction(
    () => scrub(scroll.value, last).from,
    (from, prev) => {
      if (from !== prev) runOnJS(setHop)(from);
    },
    [last],
  );
  const active = useDerivedValue(() => scrub(scroll.value, last));
  const effectName = effect ?? effectForTransition(hop);
  const source = useMemo(() => transitionEffect(effectName), [effectName]);
  const uniforms = useDerivedValue(() => ({
    progress: active.value.t,
    size: [width, height],
    touch: touch.value,
    dir: dir.value,
  }));
  const pair: [number, number] = [hop, Math.min(hop + 1, last)];

  if (count === 0 || width <= 0 || height <= 0) return null;
  const current = clamp(index, 0, last);
  return (
    <View
      style={[{ width, height }, style]}
      {...responder.panHandlers}
      accessible
      accessibilityRole="adjustable"
      accessibilityLabel={label}
      accessibilityValue={{ text: `${labels?.[current] ?? `Page ${current + 1}`}, ${current + 1} of ${count}` }}
      accessibilityActions={[{ name: "increment" }, { name: "decrement" }]}
      onAccessibilityAction={onAccessibility}
    >
      <Canvas pointerEvents="none" style={{ width, height }}>
        <TransitionPair
          pair={pair}
          pages={pages}
          source={source}
          uniforms={uniforms}
          width={width}
          height={height}
          radius={radius}
        />
      </Canvas>
    </View>
  );
}

function TransitionPair({
  pair,
  pages,
  source,
  uniforms,
  width,
  height,
  radius,
}: {
  pair: [number, number];
  pages: SkImage[];
  source: ReturnType<typeof transitionEffect>;
  uniforms: SharedValue<{
    progress: number;
    size: number[];
    touch: [number, number];
    dir: number;
  }>;
  width: number;
  height: number;
  radius: number;
}) {
  // The two textures of the active hop. Both are always bound so the shader's child order is stable;
  // at rest they are the same image and progress is 0, which returns it untouched.
  const fromImage = pages[pair[0]];
  const toImage = pages[pair[1]];
  return (
    <RoundedRect x={0} y={0} width={width} height={height} r={radius}>
      <Shader source={source} uniforms={uniforms}>
        <ImageShader image={fromImage} fit="fill" tx="clamp" ty="clamp" rect={{ x: 0, y: 0, width, height }} />
        <ImageShader image={toImage} fit="fill" tx="clamp" ty="clamp" rect={{ x: 0, y: 0, width, height }} />
      </Shader>
    </RoundedRect>
  );
}

// GL Transitions pager geometry and physics. Pure functions shared by the React Native Skia
// component and the web preview, so both compute the same scrub, snapping and effect mapping.
export const clamp = (v: number, lo = 0, hi = 1) => {
  "worklet";
  return Math.max(lo, Math.min(hi, v));
};

// Rubber band past the ends while dragging: overshoot counts at 0.38, like a stretched spring.
export function rubber(v: number, lo: number, hi: number) {
  "worklet";
  if (v < lo) return lo + (v - lo) * 0.38;
  if (v > hi) return hi + (v - hi) * 0.38;
  return v;
}

// Finger drag dx (px, positive right) maps to scroll: dragging left moves forward through pages.
export function dragScroll(start: number, dx: number, stride: number, last: number) {
  "worklet";
  return rubber(start - dx / Math.max(1, stride), 0, last);
}

// Where a released finger leaves the pager. A fast flick moves one page in the flick direction,
// even from just past the current page; a slow release settles to the nearest page.
export function snapTarget(scroll: number, velocityPages: number, last: number) {
  "worklet";
  const threshold = 0.5;
  let target: number;
  if (velocityPages > threshold) target = Math.floor(scroll + 0.02) + 1;
  else if (velocityPages < -threshold) target = Math.ceil(scroll - 0.02) - 1;
  else target = Math.round(scroll);
  return clamp(Math.round(target), 0, last);
}

// The four transition effects, in the order page hops cycle through them.
export const EFFECTS = ["ripple", "slices", "zoom", "melt"] as const;
export type TransitionEffect = (typeof EFFECTS)[number];
export const EFFECT_LABELS: Record<TransitionEffect, string> = {
  ripple: "Ripple",
  slices: "Slices",
  zoom: "Zoom",
  melt: "Melt",
};

// Each page-to-page hop uses the next effect in the cycle, so a long gallery sees them all.
export function effectForTransition(i: number): TransitionEffect {
  "worklet";
  return EFFECTS[((i % EFFECTS.length) + EFFECTS.length) % EFFECTS.length];
}

// Decompose a continuous scroll into the active hop: page `from`, page `to`, progress t in 0..1.
// At rest on the last page there is no hop: from == to == last, t == 0.
export function scrub(scroll: number, last: number) {
  "worklet";
  const s = clamp(scroll, 0, last);
  const from = Math.min(Math.floor(s), Math.max(0, last - 1));
  const t = last === 0 ? 0 : clamp(s - from, 0, 1);
  return { from, to: Math.min(from + 1, last), t };
}

// Slices effect: slice i of n starts `stagger` late; its local progress eases smoothstep.
export const SLICES = 7;
export const SLICE_STAGGER = 0.07;
export function sliceProgress(t: number, i: number, n = SLICES, stagger = SLICE_STAGGER) {
  "worklet";
  const local = clamp((t - i * stagger) / Math.max(1e-4, 1 - stagger * (n - 1)));
  return local * local * (3 - 2 * local);
}

// Melt effect: a deterministic per-column delay in [0, maxDelay), so the drip pattern never moves.
export const MELT_COLUMNS = 24;
export const MELT_MAX_DELAY = 0.45;
export function columnDelay(col: number, maxDelay = MELT_MAX_DELAY) {
  "worklet";
  const s = Math.sin(col * 12.9898) * 43758.5453;
  return (s - Math.floor(s)) * maxDelay;
}
export function meltProgress(t: number, col: number) {
  "worklet";
  const local = clamp((t - columnDelay(col)) / (1 - MELT_MAX_DELAY));
  return local * local * (3 - 2 * local);
}

// Zoom effect: the channel split peaks exactly mid-transition and vanishes at both ends.
export function channelSplit(t: number) {
  "worklet";
  return Math.sin(clamp(t) * Math.PI);
}

// Ripple effect: the wavefront eases out of and into the ends, 0..1 of the cover diagonal.
export function rippleFront(t: number) {
  "worklet";
  const x = clamp(t);
  return x * x * (3 - 2 * x);
}

// The settle spring. Slow motion stretches the same spring in time: k = 4 plays it four times
// slower (stiffness / k^2, damping / k, and the initial velocity handed to it / k).
export function springConfig(slow: boolean) {
  const k = slow ? 4 : 1;
  return { damping: 26 / k, stiffness: 320 / (k * k), mass: 1 };
}

import { Skia, type SkRuntimeEffect } from "@shopify/react-native-skia";
import type { TransitionEffect } from "./transitionMath";

// Four original transition effects as Skia runtime shaders. Every shader crossfades two page
// textures (`fromI` -> `toI`) on a 0..1 `progress` that the drag scrubs directly. Each returns
// exactly `fromI` at progress 0 and exactly `toI` at progress 1, so a page at rest is pixel-clean.

// Ripple: a wavefront grows from the touch point, revealing the next page inside it, with a faint
// light catch riding the front. The radius covers the worst-case corner so the page fully turns.
const RIPPLE = `
uniform shader fromI;
uniform shader toI;
uniform float progress;
uniform float2 size;
uniform float2 touch;
half4 main(float2 p) {
  float2 uv = p / size;
  float aspect = size.x / size.y;
  float2 d = uv - touch;
  d.x *= aspect;
  float dist = length(d);
  float maxR = length(float2(aspect, 1.0)) + 0.08;
  float e = progress * progress * (3.0 - 2.0 * progress);
  float r = e * maxR;
  float edge = 0.09;
  float m = smoothstep(r, r - edge, dist);
  half4 a = fromI.eval(p);
  half4 b = toI.eval(p);
  float ring = exp(-4.0 * pow((dist - r) / edge, 2.0));
  half glow = half(ring * 0.22 * (1.0 - abs(2.0 * progress - 1.0)));
  half4 c = mix(a, b, half(m));
  return half4(c.rgb + glow * half3(0.95, 0.85, 1.0), c.a);
}`;

// Slices: seven vertical bands of the next page slide in behind the drag direction, each starting
// a beat after its neighbour and bobbing slightly as it lands.
const SLICES = `
uniform shader fromI;
uniform shader toI;
uniform float progress;
uniform float2 size;
uniform float dir;
half4 main(float2 p) {
  float i = floor(p.x / size.x * 7.0);
  float local = clamp((progress - i * 0.07) / (1.0 - 0.07 * 6.0), 0.0, 1.0);
  local = local * local * (3.0 - 2.0 * local);
  float2 shift = float2(
    (1.0 - local) * 0.30 * dir * size.x,
    (mod(i, 2.0) - 0.5) * (1.0 - local) * size.y * 0.10
  );
  half4 a = fromI.eval(p);
  half4 b = toI.eval(p + shift);
  return mix(a, b, half(local));
}`;

// Zoom: the outgoing page leans in and fades while the incoming page settles from a slight zoom,
// its colour channels split radially - widest exactly mid-transition, closed at both ends.
const ZOOM = `
uniform shader fromI;
uniform shader toI;
uniform float progress;
uniform float2 size;
half4 main(float2 p) {
  float2 c = size * 0.5;
  float2 pa = c + (p - c) * (1.0 - 0.18 * progress);
  half4 a = fromI.eval(pa);
  float2 pb = c + (p - c) * (1.18 - 0.18 * progress);
  float2 d = (p - c) / size;
  float split = sin(progress * 3.14159265) * 0.012;
  half r = toI.eval(pb - d * split * size.x).r;
  half4 b = toI.eval(pb);
  half bl = toI.eval(pb + d * split * size.x).b;
  float m = smoothstep(0.2, 0.8, progress);
  return mix(a, half4(r, b.g, bl, b.a), half(m));
}`;

// Melt: columns of the old page slide down and let go one by one in a fixed shuffled order, like
// the picture slipping off the glass.
const MELT = `
uniform shader fromI;
uniform shader toI;
uniform float progress;
uniform float2 size;
half4 main(float2 p) {
  float col = floor(p.x / size.x * 24.0);
  float rnd = fract(sin(col * 12.9898) * 43758.5453);
  float local = clamp((progress - rnd * 0.45) / 0.55, 0.0, 1.0);
  local = local * local * (3.0 - 2.0 * local);
  half4 b = toI.eval(p);
  half4 a = fromI.eval(p + float2(0.0, local * size.y * 0.5));
  return mix(b, a, half(1.0 - local));
}`;

function compile(name: string, source: string): SkRuntimeEffect {
  const effect = Skia.RuntimeEffect.Make(source);
  if (!effect) throw new Error(`GL Transitions: the ${name} shader failed to compile`);
  return effect;
}

const compiled: Record<TransitionEffect, SkRuntimeEffect> = {
  ripple: compile("ripple", RIPPLE),
  slices: compile("slices", SLICES),
  zoom: compile("zoom", ZOOM),
  melt: compile("melt", MELT),
};

export function transitionEffect(name: TransitionEffect): SkRuntimeEffect {
  return compiled[name];
}

// The Example gallery: five original procedural landscapes, described as data so the React Native
// demo (Skia) and the web preview (Canvas 2D) render the same scenes. No third-party artwork.
export type Ridge = { color: string; base: number; amp: number; seed: number };
export type Scene = {
  title: string;
  sky: [string, string];
  body: { x: number; y: number; r: number; color: string; halo: string };
  ridges: Ridge[];
};

// Deterministic ridge silhouette: three seeded sine waves summed. x and the result are in scene
// units (0..1); base is the ridge line's resting height, amp how far the peaks wander.
export function ridgeY(ridge: Ridge, x: number): number {
  const { seed, base, amp } = ridge;
  const a = Math.sin(x * 3.1 + seed * 12.9) * 0.5;
  const b = Math.sin(x * 6.7 + seed * 78.2) * 0.3;
  const c = Math.sin(x * 13.3 + seed * 37.7) * 0.2;
  return base - amp * (a + b + c);
}

// A ridge as a closed polygon: the silhouette across n stops, then down to the bottom corners.
export function ridgePath(ridge: Ridge, width: number, height: number, stops = 26): { x: number; y: number }[] {
  const pts: { x: number; y: number }[] = [];
  for (let i = 0; i <= stops; i++) {
    const x = i / stops;
    pts.push({ x: x * width, y: ridgeY(ridge, x) * height });
  }
  pts.push({ x: width, y: height }, { x: 0, y: height });
  return pts;
}

export const SCENES: Scene[] = [
  {
    title: "Dune",
    sky: ["#f8dfae", "#eda873"],
    body: { x: 0.68, y: 0.3, r: 0.13, color: "#fff3d9", halo: "#ffe9bd55" },
    ridges: [
      { color: "#e9b478", base: 0.62, amp: 0.06, seed: 0.11 },
      { color: "#d69354", base: 0.74, amp: 0.07, seed: 0.43 },
      { color: "#b96f3c", base: 0.88, amp: 0.08, seed: 0.77 },
    ],
  },
  {
    title: "Ridge",
    sky: ["#dff0e2", "#a8cdb0"],
    body: { x: 0.3, y: 0.26, r: 0.11, color: "#fdfbe8", halo: "#f5f2cf55" },
    ridges: [
      { color: "#8fb894", base: 0.58, amp: 0.08, seed: 0.29 },
      { color: "#5f9468", base: 0.72, amp: 0.09, seed: 0.61 },
      { color: "#315843", base: 0.88, amp: 0.08, seed: 0.87 },
    ],
  },
  {
    title: "Harbor",
    sky: ["#c9def2", "#7fa8d4"],
    body: { x: 0.74, y: 0.34, r: 0.12, color: "#f4f0dc", halo: "#e9e4c455" },
    ridges: [
      { color: "#6e92bd", base: 0.6, amp: 0.05, seed: 0.19 },
      { color: "#44678f", base: 0.74, amp: 0.07, seed: 0.53 },
      { color: "#223d5c", base: 0.9, amp: 0.07, seed: 0.71 },
    ],
  },
  {
    title: "Valley",
    sky: ["#eeddf2", "#c19fd6"],
    body: { x: 0.24, y: 0.3, r: 0.12, color: "#fff1e4", halo: "#ffd9c455" },
    ridges: [
      { color: "#a97fbd", base: 0.6, amp: 0.07, seed: 0.37 },
      { color: "#7c539a", base: 0.75, amp: 0.08, seed: 0.59 },
      { color: "#452f5e", base: 0.9, amp: 0.07, seed: 0.83 },
    ],
  },
  {
    title: "Night",
    sky: ["#27304d", "#0d1322"],
    body: { x: 0.7, y: 0.24, r: 0.1, color: "#f2efe2", halo: "#dfe3f055" },
    ridges: [
      { color: "#2c3757", base: 0.62, amp: 0.07, seed: 0.23 },
      { color: "#1b2440", base: 0.76, amp: 0.08, seed: 0.67 },
      { color: "#0a0f1e", base: 0.9, amp: 0.07, seed: 0.91 },
    ],
  },
